import{_ as o,o as i,c as n,a2 as a}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0065 — Presenza in tempo reale sui vault condivisi: avatar e cursori live (M25)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0065-presenza-in-tempo-reale.md","filePath":"adr/0065-presenza-in-tempo-reale.md"}'),t={name:"adr/0065-presenza-in-tempo-reale.md"};function r(s,e,c,l,d,p){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0065-—-presenza-in-tempo-reale-sui-vault-condivisi-avatar-e-cursori-live-m25" tabindex="-1">ADR-0065 — Presenza in tempo reale sui vault condivisi: avatar e cursori live (M25) <a class="header-anchor" href="#adr-0065-—-presenza-in-tempo-reale-sui-vault-condivisi-avatar-e-cursori-live-m25" aria-label="Permalink to &quot;ADR-0065 — Presenza in tempo reale sui vault condivisi: avatar e cursori live (M25)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-20; recepita nello spec v1.9)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-20</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>A-05 (<code>Specifications.md:73</code>); §0.3 e §2.6.4 («Collaborazione asincrona», <code>:568</code>); D-04 (<code>:1957</code>); V-01 (<code>:56</code>); §3.7 (riga «Web UI», CSP, <code>:1545</code>); §2.6.6 (tabella dei feature flag, righe <code>features.*</code> da <code>:599</code>); ADR-0050; ADR-0060; <code>docs/security/data-retention.md</code></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì:</strong> A-05, §2.6.4 e D-04 escludono la presenza; V-01 elenca REST e gRPC; la CSP di §3.7 non prevede WebSocket. Righe da aggiornare nello spec (a cura dell&#39;owner) in «Conseguenze»</td></tr><tr><td><strong>Superfici</strong></td><td>desktop e workbench web (stesso core Go, desktop e WASM; prove: vitest di <code>@clarae/ui</code> e <code>packages/workbench/src/presence/</code>, e2e sul mock dei binding, test del client del core contro un server WebSocket finto, voce <code>presence</code> nel registro di parità); cloud (test dell&#39;hub, integrazione con due «repliche» sullo stesso PostgreSQL); console: nessun cambiamento oltre al flag nel Config Profile. Prove reali con più utenti: da fare</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.9 (20 novembre 2026): V-01, A-05, §2.2.1 (riga «Web viewer»), §2.6.4, §2.6.6 (riga <code>features.presence</code>), §3.7, D-04, C.2, C.4 e registro delle revisioni, con i punti facoltativi; applicata da <a href="./../spec-v1.9-proposta.html"><code>docs/spec-v1.9-proposta.md</code></a></td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-20: togliere il pulsante «Nuova applicazione» dalla barra dell&#39;esploratore e al suo posto mostrare gli avatar degli <strong>altri</strong> utenti che hanno aperto lo stesso file; sopra il documento, i loro <strong>cursori live</strong> (puntatore con etichetta col nome). Colore deterministico per utente, uguale per avatar e cursore. Rilascio 1.8.2 (M25).</p><p>Lo stato di partenza:</p><ul><li>Lo spec esclude la presenza: A-05 («editing simultaneo in tempo reale (CRDT, presenza) non è previsto», <code>Specifications.md:73</code>), §2.6.4 («non c&#39;è editing simultaneo né presenza», <code>:568</code>) e D-04 (<code>:1957</code>).</li><li>ADR-0050 lascia il co-editing (Yjs, seam in <code>editor/live/collab/providers.ts</code>) implementato ma <strong>spento</strong>.</li><li>Non esiste un canale client→cloud in tempo reale: <code>internal/notify</code> è solo server→client (SSE e gRPC) e tra repliche usa PostgreSQL <code>LISTEN/NOTIFY</code> (<code>services/cloud/internal/notify/hub.go</code>). Il cloud non ha WebSocket.</li><li>Nei profili c&#39;è solo <code>display_name</code>, nessun avatar. MUI non è nel progetto.</li><li>Il pulsante da togliere è in <code>packages/workbench/src/sidebar/FileExplorer.tsx:483-495</code> (<code>data-testid=&quot;explorer-new-application&quot;</code>); lo aveva introdotto <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a>.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>1. Che cosa è.</strong> Presenza e puntatori degli altri utenti sullo stesso file, <strong>solo nei vault condivisi</strong>. <strong>Non</strong> è co-editing: nessun CRDT, nessun Yjs acceso, nessuna modifica al merge sul client (D-04 resta per il contenuto). <a href="./0050-ai-inattiva-e-collab-spento.html">ADR-0050</a> resta com&#39;è. I vault privati sono esclusi: non hanno altri utenti e il server non vede i loro percorsi (D-02).</p><p><strong>2. Flag.</strong> <code>features.presence</code>, default <strong><code>true</code></strong>, spegnibile dal Config Profile (schema <code>api/config-profile.schema.json</code>, copia in <code>shared/go/features</code>, tabella della guida admin). Spento: il server rifiuta il join con <code>presence-disabled</code> e chiude; il client non apre la connessione e non mostra nulla. Capability <code>presence</code> (desktop e workbench web).</p><p><strong>3. Componenti.</strong> <code>Avatar</code> e <code>AvatarGroup</code> propri in <code>@clarae/ui</code> (<code>max</code>, <code>spacing</code>, <code>+N</code>, tooltip col nome, bordo del colore dello sfondo). <strong>Differenza da MUI:</strong> qui <code>max</code> conta gli avatar <strong>mostrati</strong> (predefinito 4) e <code>+N</code> è il <strong>resto</strong>; in MUI <code>max</code> include il badge <code>+N</code>. Niente MUI. Il colore è <code>getUserColor(userId)</code>, deterministico, da una palette fissa di <strong>otto token</strong> <code>--presence-1…8</code> (con il testo <code>--presence-N-fg</code>, nel tema chiaro e scuro: <code>packages/workbench/src/styles/tokens.css</code>), con test di contrasto WCAG AA come per gli altri token (testo a 4,5:1, segno a 3:1 sullo sfondo). Il pulsante «Nuova applicazione» sparisce dalla barra dell&#39;esploratore e al suo posto stanno gli avatar (nulla se non ci sono altri utenti). Il comando <code>app:new</code> resta in ribbon, menu contestuali, palette e stato vuoto.</p><p><strong>4. Cursore.</strong> Nelle note il cursore è il <strong>puntatore ancorato al testo</strong>: <code>{k:&quot;text&quot;,line,col}</code> (riga e colonna sotto il puntatore), ricalcolato dal ricevente sul proprio layout. Nei disegni e nei canvas è in <strong>coordinate di scena</strong>: <code>{k:&quot;scene&quot;,x,y}</code>. I cursori ci sono <strong>solo per note, disegni e canvas</strong>; lettura, basi, PDF, immagini e applicazioni: solo avatar. <strong>Nelle note il cursore segue solo il <code>pointermove</code></strong> (il puntatore del mouse): il caret di chi scrive non viene inviato. In Live Preview la riga è esatta e la <strong>colonna è approssimata</strong> dentro un blocco (come per ADR-0049). Nei disegni e nei canvas la posizione è di scena e il ricevente la ricalcola con il proprio zoom e scroll. Overlay SVG con etichetta, transizione 80 ms, <code>pointer-events: none</code>; con <code>prefers-reduced-motion</code> la transizione è tolta. Invio con throttle di 40 ms, nel core, latest-wins.</p><p><strong>5. Contratto di trasporto.</strong></p><ul><li><strong>Stanza</strong> = <code>(vault cloud, file_id)</code>: gli UUID del server, stabili tra proprietario e mount di cartella. I file mai sincronizzati (senza <code>file_id</code>) non hanno presenza.</li><li><strong>WebSocket</strong> <code>GET /api/v1/presence</code>, rotta <strong>fuori dal router generato</strong>, come <code>/events</code>: si aggiunge a <code>x-clarae-external-routes</code> in <code>api/openapi.yaml</code>, con la stessa autenticazione bearer e lo stesso limite di frequenza. Il browser non può mandare header: il <strong>primo frame</strong> è <code>{&quot;t&quot;:&quot;auth&quot;,&quot;token&quot;:…}</code>. Poi JSON, un messaggio per frame. Il frame <code>auth</code> ha 10 s per arrivare (altrimenti <code>unauthenticated</code>, close 4401) e può pesare fino a <strong>8 KiB</strong> (un JWT supera spesso 1 KiB); ogni altro frame del client è di al più 1 KiB. Un browser è ammesso solo dalla stessa origine (più <code>WEB_UI_ORIGIN</code> per lo sviluppo): l&#39;<em>origin check</em> è quello di <code>coder/websocket</code>; un client senza <code>Origin</code> (il desktop) passa sempre.</li><li><strong>Client→server:</strong> <code>join {room:{vault,file}}</code>, <code>leave {room}</code>, <code>move {room,pos}</code> (<code>pos</code> opaco, ≤ 256 B), <code>auth</code> (rinnovo prima della scadenza del token, stesso utente), <code>ping</code>.</li><li><strong>Server→client:</strong> <code>ready {sid}</code>, <code>members {room,list:[{sid,user_id,name}]}</code> (la lista del server <strong>include chi ha fatto il <code>join</code></strong>: a escludere sé stessi e gli altri dispositivi dello stesso utente è il core), <code>joined {room,member}</code>, <code>left {room,sid}</code>, <code>move {room,sid,pos}</code> (mai rispedito al mittente), <code>pong</code>, <code>error {code, room?}</code>. Un <code>error</code> con <code>room</code> riguarda quella sola stanza e la connessione resta aperta (per esempio <code>forbidden</code> dopo una revoca, <code>not-found</code>, <code>vault-encrypted</code>, <code>too-many-rooms</code>, <code>not-joined</code>, <code>bad-frame</code>, <code>frame-too-large</code>); senza <code>room</code> il server chiude dopo il frame.</li><li><strong>Codici e close code.</strong> <code>unauthenticated</code> e <code>token-expired</code> chiudono con <strong>4401</strong>; <code>user-suspended</code> e <code>presence-disabled</code> con <strong>4403</strong>; <code>rate-limited</code> (oltre 32 connessioni dell&#39;utente su quella replica) con <strong>1013</strong>, e il client riprova più tardi; <code>slow-consumer</code> con 1008; <code>internal</code> con 1011. I <code>Refresh</code> del core sono serializzati e limitati alle chiavi fotografate. Il core non riprova dopo <code>presence-disabled</code> e <code>user-suspended</code>.</li><li><strong>Identità timbrata dal server:</strong> <code>user_id</code>, <code>display_name</code> e <code>sid</code> (id di sessione) vengono dal token e dal server, mai dal client.</li><li><strong>Autorizzazione per file</strong> al <code>join</code> con <code>sharing.Authorize</code>/<code>Evaluator</code> (<code>services/cloud/internal/sharing/authorize.go</code>), almeno <em>viewer</em> su quel file; <strong>ricontrollata</strong> su <code>share_changed</code>, revoca, sospensione dell&#39;utente e scadenza del token (l&#39;utente perde la stanza, non l&#39;intera connessione se ne ha altre).</li><li><strong>Limiti:</strong> frame ≤ 1 KiB (<code>auth</code> ≤ 8 KiB); <code>pos</code> ≤ 256 B; <strong>token bucket di 40 <code>move</code>/s</strong> per connessione: oltre il budget l&#39;ultima posizione di ogni stanza è <strong>trattenuta</strong> e inviata appena il budget lo consente (vince l&#39;ultima, nulla viene scartato in silenzio); ≤ <strong>32 connessioni per utente <em>per replica</em></strong> (il limite non è globale: con N repliche un utente può averne fino a 32·N); ≤ 16 stanze per connessione. <strong>Heartbeat:</strong> il server manda un ping WebSocket ogni 30 s e chiude se il pong non arriva in 20 s; il core manda un <code>ping</code> applicativo ogni 25 s (il server risponde <code>pong</code>). <strong>Ricontrollo:</strong> i permessi e il flag si rivalutano a ogni <code>share_changed</code>, <code>account_changed</code> e <code>config_changed</code> e comunque <strong>ogni 60 s</strong>; inoltre, a ogni <code>vault_changed</code> (un commit, per esempio uno spostamento di file fuori dallo scope di una share), le stanze di quel vault si ricontrollano <strong>al più ogni 5 s per sessione</strong> (<code>VaultRecheckEvery</code>): chi esce dallo scope è espulso dalla stanza in circa 5 s. Il <code>join</code> è autorizzato e la lista dei membri letta in modo atomico (<code>Hub.Members</code>): non c&#39;è un <code>join</code> che salti il controllo.</li><li><strong>Fan-out:</strong> in memoria sulla replica; tra repliche con PostgreSQL <code>NOTIFY</code> sul canale <code>presence</code>. Gli ingressi e le uscite (<code>join</code>/<code>leave</code>) vanno sempre a tutte le repliche, così ognuna conosce ogni stanza; i <code>move</code> solo se la stanza ha membri su altre repliche, coalescenti a ~15 Hz (66 ms). Ogni replica ripete i propri membri ogni <strong>20 s</strong> (heartbeat, accodato sotto lock e mai scartato: coda fino a 100000 messaggi, <code>NOTIFY</code> a blocchi di 500); un membro remoto che nessuno rinnova scade dopo <strong>70 s</strong> (TTL). Quando una replica riprende l&#39;ascolto manda un <code>hello</code> e le altre rispondono annunciando i loro membri: così si ricostruisce ciò che un&#39;interruzione del listener ha fatto perdere. Il carico di ogni messaggio è sotto i 7500 byte (limite di PostgreSQL: 8000). Nessun Redis o NATS. Chiusura ordinata (drain) allo spegnimento.</li><li><strong>Nessuna persistenza, nessun audit, nessun log per frame.</strong> Apertura e chiusura di una connessione sono solo log di livello <em>debug</em> con <code>user_id</code> e <code>sid</code>, senza contenuto né posizioni. <strong>Deciso dall&#39;owner:</strong> nessuna metrica Prometheus della presenza nella 1.8.2 (scostamento dall&#39;idea iniziale dell&#39;ADR, accettato).</li></ul><p><strong>6. Core.</strong> Il client WebSocket è codice Go condiviso (desktop e build <code>GOOS=js</code>), perché il core WASM non ha gRPC. Binding <code>PresenceAPI</code>: <code>Watch(vaultId, path) → {watching, reason}</code>, <code>Unwatch(vaultId, path)</code>, <code>Move(vaultId, path, pos)</code>. Eventi <code>presence:members {vaultId,path,members}</code> (esclusi il proprio <code>sid</code> <strong>e lo stesso <code>user_id</code> da altri dispositivi</strong>: sono «gli altri utenti»), <code>presence:move {vaultId,path,sid,pos}</code> (coalescente) e <code>presence:cleared {vaultId,path}</code> (chiusura del file, cambio file, disconnessione). Il percorso del vault si traduce in <code>(vault cloud, file_id)</code> dallo stato di sync, anche per i mount. La connessione si apre solo con almeno un file osservato in un vault condiviso collegato e si chiude dopo 30 s senza stanze.</p><p><strong>7. Registro di parità.</strong> Voce <code>presence</code> in <code>shared/parity/features.yaml</code>: desktop sì, workbench sì, con la prova sul core WASM (ADR-0045).</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>MUI</strong> — scartata: aggiunge una libreria di componenti e un motore di stili che la CSP della console (<code>style-src &#39;self&#39;</code>) non ammette senza stili inline, aggira i token di colore e pesa sul budget iniziale della console (<a href="./0061-budget-iniziale-console-720.html">ADR-0061</a>); i due componenti servono in poche decine di righe.</li><li><strong>Un POST per ogni movimento sullo stream esistente (SSE/gRPC)</strong> — scartata: 25 richieste al secondo per utente, ciascuna autenticata, con latenza e ordine non garantiti; e lo stream resta server→client.</li><li><strong>gRPC bidirezionale</strong> — scartata: il core WASM non ha gRPC, e la presenza deve funzionare identica nel workbench web.</li><li><strong>Redis o NATS tra le repliche</strong> — scartata: un servizio in più da installare e proteggere; PostgreSQL c&#39;è già e <code>LISTEN/NOTIFY</code> è già usato da <code>internal/notify</code>. Il rischio di carico è accettato con coalescenza e invio solo se servono (vedi Conseguenze).</li><li><strong>Posizione del cursore in pixel nelle note</strong> — scartata: dipende da larghezza, carattere e Live Preview del ricevente; il puntatore ancorato al testo (riga e colonna) resta corretto a ogni layout.</li><li><strong>Presenza sui vault privati</strong> — scartata: nessun altro utente, e il server non conosce i percorsi (E2EE, D-02).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Il cloud ha il suo primo canale client→cloud in tempo reale.</strong> Ingress, proxy e bilanciatori devono lasciare passare l&#39;upgrade WebSocket e non chiudere connessioni inattive prima del ping del server (30 s): timeout e annotazioni in <code>deploy/</code>. In Helm c&#39;è un <strong>Ingress dedicato</strong> (<code>&lt;release&gt;-presence</code>, path esatto <code>/api/v1/presence</code>) con <code>proxy-read-timeout</code> e <code>proxy-send-timeout</code> presi da <code>ingress.presence.timeoutSeconds</code> (3600; <code>ingress.presence.annotations</code> per altri controller); in Compose, Caddy aggiorna la connessione da solo e non ha timeout di inattività. Da verificare su un ingress vero.</li><li><strong>Carico di PostgreSQL <code>NOTIFY</code>:</strong> a ogni <code>move</code> coalescente. Mitigazione: notifica solo con membri su altre repliche, ~15 Hz, payload ≤ 1 KiB. Da misurare con più repliche.</li><li><strong>Privacy:</strong> gli altri utenti del file vedono nome visualizzato e posizione del puntatore finché il file è aperto; nulla viene salvato. <code>docs/security/data-retention.md</code> va aggiornato con la riga «presenza: solo in memoria, nessuna persistenza, nessun audit» e con l&#39;avvertenza che l&#39;amministratore può spegnere il flag.</li><li><strong>Il core WASM apre una connessione WebSocket</strong> dal browser: la CSP del workbench ha <code>connect-src &#39;self&#39; blob:</code> più l&#39;issuer, e <code>&#39;self&#39;</code> copre <code>wss:</code> sulla stessa origine nei browser attuali; va provato su Safari, dove la corrispondenza di <code>&#39;self&#39;</code> con <code>ws:</code>/<code>wss:</code> è storicamente diversa (eventualmente aggiungere <code>wss://&lt;origine&gt;</code> esplicito).</li><li><strong>Nessuna prova reale con più utenti</strong> in questa milestone: i test sono automatici (hub, due repliche sullo stesso PostgreSQL, server finto); il manuale con due utenti (desktop e web) resta a carico dell&#39;owner.</li><li><strong>Il pulsante «Nuova applicazione» esce dalla barra dell&#39;esploratore:</strong> <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a> ne è emendata nella parte che lo introduceva; <code>app:new</code> resta raggiungibile da ribbon, menu contestuali, palette e stato vuoto. Vanno aggiornati i test e gli e2e che usano <code>explorer-new-application</code>.</li><li><strong>ADR-0050 resta in vigore:</strong> la presenza non accende il co-editing, il seam Yjs resta spento.</li><li><strong>Spec da aggiornare (recepite il 2026-11-20 nello spec v1.9, <a href="./../spec-v1.9-proposta.html"><code>docs/spec-v1.9-proposta.md</code></a>):</strong><ul><li>A-05 (<code>:73</code>): la presenza (avatar e cursori) è prevista nei vault condivisi; resta escluso l&#39;editing simultaneo (CRDT).</li><li>§2.6.4 (<code>:568</code>): non c&#39;è editing simultaneo; c&#39;è la <strong>presenza</strong> (avatar e cursori degli altri utenti sullo stesso file, solo vault condivisi).</li><li>D-04 (<code>:1957</code>, e §0.3): aggiungere «presenza in tempo reale, senza persistenza».</li><li>V-01 (<code>:56</code>): API REST e gRPC, più <strong>WebSocket</strong> per la sola presenza.</li><li>§3.7 (riga «Web UI», <code>:1545</code>): <code>connect-src</code> con WebSocket verso la stessa origine; §2.6.6: nuova riga <code>features.presence</code> (acceso, spegnibile).</li><li>Privacy: riga di <code>docs/security/data-retention.md</code> (non è nello spec), e Appendice C.4 per l&#39;elenco degli ADR recepiti.</li></ul></li><li><strong>Da rivedere:</strong> il limite di 40 <code>move</code>/s e la coalescenza a ~15 Hz dopo le misure con più utenti; l&#39;avatar con immagine (oggi solo iniziali e colore), se il profilo avrà una foto.</li></ul>',19)])])}const m=o(t,[["render",r]]);export{g as __pageData,m as default};
